        count_meetings = bin(mask).count('1')
        if count_meetings > best_mask or (count_meetings == best_mask and time < best_time):
            best_mask = count_meetings
            best_time = time
            best_itinerary = itinerary

        for i in range(n):
            if mask & (1 << i):
