                continue
            travel_time = travel_times[loc][friend_loc]
            arrival_time = time + travel_time
            start_meeting = max(arrival_time, friend[3])
            if start_meeting + friend[5] <= friend[4]:
                new_time = start_meeting + friend[5]
                new_mask = mask | (1 << i)
                new_loc = friend_loc
                if new_time < dist[(new_loc, new_mask)]:
                    dist[(new_loc, new_mask)] = new_time
                    new_itinerary = itinerary + [{
